import {WIDGETS,GRID,placeWidget} from './dashboard-model.js';
import {freshness} from './services.js';
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export class DashboardView {
  constructor(root,{change,command,detail,notify}){this.root=root;this.change=change;this.command=command;this.detail=detail;this.notify=notify;this.editing=false;this.snapshot=null;this.online=true;this.pending=false;this.abort=new AbortController();const options={signal:this.abort.signal};
    root.addEventListener('pointerdown',e=>this.start(e),options);root.addEventListener('pointermove',e=>this.move(e),options);root.addEventListener('pointerup',e=>this.end(e),options);root.addEventListener('pointercancel',()=>this.cancel(),options);root.addEventListener('lostpointercapture',()=>this.cancel(),options);root.addEventListener('keydown',e=>this.key(e),options);
    root.addEventListener('click',e=>{const action=e.target.closest('[data-action]');if(action){this.command(action.dataset.action,action.dataset.action==='home.lights'?!this.snapshot.home.lightsOn:undefined);return;}const title=e.target.closest('[data-detail]');if(title&&!this.editing){this.detail(title.closest('.widget').dataset.type);return;}if(!this.editing&&!e.target.closest('button,input')){const card=e.target.closest('.widget');if(card)this.detail(card.dataset.type);}},options);
    root.addEventListener('change',e=>{if(e.target.matches('[data-volume]'))this.command('media.volume',Number(e.target.value));},options);
    this.animation=setInterval(()=>{if(!document.hidden)this.drawCameras();},1000);
  }
  setLayout(dashboard,editing){this.layout=dashboard;this.editing=editing;this.root.style.setProperty('--widget-opacity',dashboard.opacity);this.root.style.setProperty('--widget-gap',dashboard.gap+'px');const focusedId=document.activeElement?.closest('.widget')?.dataset.id;const focusedTitle=document.activeElement?.matches('.title');const scrollTop=this.root.parentElement.scrollTop;this.root.replaceChildren();for(const w of dashboard.widgets){const card=document.createElement('article');card.className='widget'+(editing?' editing':'');card.dataset.id=w.id;card.dataset.type=w.type;card.style.gridColumn=`${w.x+1} / span ${w.w}`;card.style.gridRow=`${w.y+1} / span ${w.h}`;card.setAttribute('aria-label',WIDGETS[w.type].name);
      card.innerHTML=`<div class="widget-header"><button class="title" data-detail aria-label="${editing?'Move or resize':'Open'} ${esc(WIDGETS[w.type].name)}"><span class="widget-symbol">${WIDGETS[w.type].icon}</span>${esc(WIDGETS[w.type].name)}</button><span class="widget-detail" aria-hidden="true">${editing?'⠿':'↗'}</span></div><div class="widget-body"></div><button class="resize-handle" tabindex="-1" aria-label="Resize ${esc(WIDGETS[w.type].name)}"></button>`;this.root.append(card);}
    this.root.parentElement.scrollTop=scrollTop;this.renderData();if(focusedTitle&&focusedId){[...this.root.children].find(c=>c.dataset.id===focusedId)?.querySelector('.title').focus({preventScroll:true});}
  }
  setData(snapshot,online=true,pending=false){this.snapshot=snapshot;this.online=online;this.pending=pending;this.renderData();}
  renderData(){const d=this.snapshot;for(const card of this.root.querySelectorAll('.widget')){const type=card.dataset.type;const body=card.querySelector('.widget-body');if(body.contains(document.activeElement)&&document.activeElement.matches("input")&&!this.pending)continue;const unavailable=!d||d.sources[WIDGETS[type].source]!=='online';card.classList.toggle('unavailable',unavailable);if(!d){body.innerHTML='<div class="widget-unavailable">Waiting for the hub…</div>';continue;}const disabled=!this.online||this.pending||freshness(d)==='stale'||unavailable?'disabled':'';
      switch(type){
        case 'home':body.innerHTML=`<div class="metric">${d.home.temperature.toFixed(1)}<small>°C</small></div><div class="bottom-line"><span>${d.home.devices} devices</span><button class="mini-action" data-action="home.lights" ${disabled}>Lights ${d.home.lightsOn?'on':'off'}</button></div>`;break;
        case 'weather':body.innerHTML=`<span class="weather-icon" aria-hidden="true">☀</span><div class="metric">${d.weather.temperature}<small>°</small></div><div class="bottom-line"><span>H ${d.weather.high}° · L ${d.weather.low}°</span><span>Demo</span></div>`;break;
        case 'system':body.innerHTML=`<div class="metric">${d.system.cpu}<small>% CPU</small></div><div class="bottom-line"><span>RAM ${d.system.memory}%</span><span>${Math.floor(d.system.uptime/86400)}d uptime</span></div>`;break;
        case 'camera':{const cam=d.camera;body.innerHTML=`<div class="camera-surface">${cam.mode==='simulation'?'<canvas width="480" height="270" aria-label="Simulated garden camera preview"></canvas>':cam.mode==='mjpeg'?`<img src="${esc(cam.url)}" alt="${esc(cam.name)} camera stream">`:'<span>Camera unavailable</span>'}<span class="feed-label">${cam.mode==='simulation'?'SIMULATED FEED':'HUB CAMERA'}</span><span class="feed-time"></span></div><div class="bottom-line"><span>${esc(cam.name)}</span><span>${cam.mode==='simulation'?'Demo':'MJPEG'}</span></div>`;const image=body.querySelector('img');if(image)image.onerror=()=>{image.replaceWith(document.createTextNode('Stream unavailable'));};break;}
        case 'media':body.innerHTML=`<div class="music-art" aria-hidden="true"></div><div class="track-info"><div class="track-title">${esc(d.media.title)}</div><div class="track-artist">${esc(d.media.artist)}</div></div><div class="media-controls"><button data-action="media.previous" aria-label="Previous track" ${disabled}>⏮</button><button class="play" data-action="${d.media.playing?'media.pause':'media.play'}" aria-label="${d.media.playing?'Pause':'Play'} demo music" ${disabled}>${d.media.playing?'Ⅱ':'▶'}</button><button data-action="media.next" aria-label="Next track" ${disabled}>⏭</button></div><label class="volume">Volume<input type="range" min="0" max="100" value="${d.media.volume}" data-volume ${disabled}></label><div class="caption">Spotify controls · simulated</div>`;break;
        case 'energy':body.innerHTML=`<div class="energy-layout"><div class="energy-stat"><div class="metric">${d.energy.watts}<small>W</small></div><div class="caption">${d.energy.today} kWh today</div></div><div class="energy-chart" role="img" aria-label="Energy usage over the last 24 readings">${d.energy.history.map(v=>`<i style="height:${Math.max(4,v/Math.max(...d.energy.history)*100)}%"></i>`).join('')}</div><div class="energy-stat"><div class="metric">${d.air.humidity}<small>%</small></div><div class="caption">Humidity</div></div></div>`;break;
        case 'air':body.innerHTML=`<div class="metric">${d.air.co2}<small>ppm</small></div><div class="caption">Indoor CO₂</div><div class="bottom-line">Humidity ${d.air.humidity}%</div>`;break;
        case 'network':body.innerHTML=`<div class="metric">${d.network.latency}<small>ms</small></div><div class="caption">Hub latency</div><div class="bottom-line">${d.network.clients} connected clients</div>`;break;
      }
      if(unavailable||(!this.online&&type==='camera')){const overlay=document.createElement('div');overlay.className='widget-unavailable';overlay.textContent=this.online?'Source unavailable':'Camera connection lost';body.append(overlay);}
    }this.drawCameras();
  }
  drawCameras(){for(const c of this.root.querySelectorAll('canvas')){const ctx=c.getContext('2d'),w=c.width,h=c.height;const t=Date.now()/1000;ctx.fillStyle='#829da0';ctx.fillRect(0,0,w,h);ctx.fillStyle='#314f42';ctx.fillRect(0,80,w,190);ctx.fillStyle='#adab98';ctx.beginPath();ctx.moveTo(180,95);ctx.lineTo(300,95);ctx.lineTo(410,h);ctx.lineTo(65,h);ctx.fill();ctx.fillStyle='#446450';for(let i=0;i<20;i++){const x=i*29;ctx.fillRect(x,65,19,30+Math.sin(i)*12);}ctx.strokeStyle='#bdbea8';ctx.lineWidth=2;for(let i=0;i<5;i++){const y=100+i*i*8;ctx.beginPath();ctx.moveTo(140-i*18,y);ctx.lineTo(340+i*18,y);ctx.stroke();}ctx.fillStyle='#38433f';ctx.fillRect(315,145,110,14);ctx.fillRect(324,159,7,48);ctx.fillRect(407,159,7,48);for(let i=0;i<5;i++){const x=35+i*90;ctx.fillStyle='#4e6253';ctx.fillRect(x,94,4,40);ctx.fillStyle='#65916c';ctx.beginPath();ctx.ellipse(x+3+Math.sin(t*.4+i)*2,90,22,27,0,0,Math.PI*2);ctx.fill();}ctx.fillStyle='#111b2422';for(let y=0;y<h;y+=4)ctx.fillRect(0,y,w,1);c.parentElement.querySelector('.feed-time').textContent=new Date().toLocaleTimeString();}}
  start(e){if(!this.editing||e.button!==0)return;const handle=e.target.closest('.resize-handle'),header=e.target.closest('.widget-header');if(!handle&&!header)return;const card=e.target.closest('.widget'),w=this.layout.widgets.find(w=>w.id===card.dataset.id);e.preventDefault();const r=this.root.getBoundingClientRect(),gap=parseFloat(getComputedStyle(this.root).gap)||0;this.drag={id:w.id,original:{...w},x:e.clientX,y:e.clientY,cellX:(r.width+gap)/GRID.columns,cellY:parseFloat(getComputedStyle(this.root).gridAutoRows)+gap,scrollTop:this.root.parentElement.scrollTop,resize:!!handle,pointer:e.pointerId,patch:{},card};card.classList.add('dragging');this.root.setPointerCapture(e.pointerId);}
  move(e){if(!this.drag)return;const d=this.drag,dx=Math.round((e.clientX-d.x)/d.cellX),dy=Math.round((e.clientY-d.y+this.root.parentElement.scrollTop-d.scrollTop)/d.cellY);d.patch=d.resize?{w:Math.max(2,Math.min(6-d.original.x,d.original.w+dx)),h:Math.max(2,Math.min(GRID.rows-d.original.y,d.original.h+dy))}:{x:Math.max(0,Math.min(6-d.original.w,d.original.x+dx)),y:Math.max(0,Math.min(GRID.rows-d.original.h,d.original.y+dy))};const w={...d.original,...d.patch};d.card.style.gridColumn=`${w.x+1} / span ${w.w}`;d.card.style.gridRow=`${w.y+1} / span ${w.h}`;}
  end(e){if(!this.drag)return;const d=this.drag;this.drag=null;if(this.root.hasPointerCapture(e.pointerId))this.root.releasePointerCapture(e.pointerId);try{const next=placeWidget(this.layout,d.id,d.patch);this.change(next);}catch(error){this.notify(error.message);this.setLayout(this.layout,this.editing);}}
  cancel(){if(this.drag){this.drag=null;this.setLayout(this.layout,this.editing);}}
  key(e){if(!this.editing||!e.target.matches('.title')||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const id=e.target.closest('.widget').dataset.id,w=this.layout.widgets.find(w=>w.id===id);const dx=e.key==='ArrowLeft'?-1:e.key==='ArrowRight'?1:0,dy=e.key==='ArrowUp'?-1:e.key==='ArrowDown'?1:0;try{this.change(placeWidget(this.layout,id,e.shiftKey?{w:w.w+dx,h:w.h+dy}:{x:w.x+dx*w.w,y:w.y+dy*w.h}));}catch(error){this.notify(error.message);}}
  dispose(){clearInterval(this.animation);this.abort.abort();}
}
